"""Credential Manager and Vault container parsers.

Credential Manager files (``Credentials\\<hash>``) and Vault policy files
(``Policy.vpol``) wrap one or more DPAPI blobs inside a container header, so they are
not bare blobs: the blob begins four bytes before the provider GUID. Vault credential
files (``*.vcrd``) are not DPAPI-protected at all; their attributes are AES-encrypted
under the keys recovered from the matching ``Policy.vpol``.
"""
import struct

from Crypto.Cipher import AES

from .blob import DpapiBlob, PROVIDER_GUID_LE

# The "Internet Explorer" / Web Credentials vault schema.
WEB_CREDENTIAL_SCHEMA = '3ccd5499-87a8-4b10-a215-608888dd3b55'


def _u32(buf, off):
    return struct.unpack('<L', buf[off:off + 4])[0]


def _blob_offsets(data):
    """Offsets of every DPAPI blob in a container (each starts 4 bytes before a GUID)."""
    offsets = []
    start = 0
    while True:
        pos = data.find(PROVIDER_GUID_LE, start)
        if pos < 4:
            break
        offsets.append(pos - 4)
        start = pos + 16
    return offsets


class CredentialFile:
    """A Credential Manager file: one wrapped DPAPI blob."""

    def __init__(self, data):
        offsets = _blob_offsets(data)
        if not offsets:
            raise ValueError('no DPAPI blob in credential file')
        self.blob = DpapiBlob(data[offsets[0]:])
        self.cleartext = None

    def decrypt(self, master_key, entropy=None):
        self.cleartext = self.blob.decrypt(master_key, entropy=entropy)
        return self.cleartext

    def fields(self):
        """Best-effort CREDENTIAL fields from the decrypted cleartext.

        Returns a dict with the last-written time and the sequence of UTF-16 strings
        (target, alias, comment, username ...) the structure carries. The trailing
        secret is returned as raw bytes under ``secret``.
        """
        if self.cleartext is None:
            return None
        buf = self.cleartext
        info = {}
        if len(buf) >= 32:
            info['last_written_filetime'] = struct.unpack('<Q', buf[24:32])[0]
        strings = []
        o = 36
        # The structure is a run of length-prefixed UTF-16 strings; walk them defensively.
        while o + 4 <= len(buf):
            slen = _u32(buf, o)
            o += 4
            if slen == 0 or o + slen > len(buf) or slen > 2048 or slen % 2:
                break
            strings.append(buf[o:o + slen].decode('utf-16-le', 'replace').rstrip('\x00'))
            o += slen
        info['strings'] = strings
        info['secret'] = buf[o:]
        return info


def _bcrypt_key_bytes(cleartext):
    """Extract the AES key bytes from a decrypted VAULT_POL key structure.

    The decrypted blob holds a small header, a GUID and a key container whose last
    field is the raw AES key. The key container is located by its ``size`` prefix.
    """
    # Layout: DWORD keyCount/size; GUID(16); DWORD; DWORD; then key container:
    #   DWORD cbKey; ... 'KSSM'/bcrypt header ... key bytes at the tail.
    # The reliable anchor is the final DWORD-sized length that leaves exactly that
    # many bytes to the end; fall back to known AES sizes.
    for key_len in (32, 24, 16):
        tail = cleartext[-key_len:]
        if len(tail) == key_len:
            # verify there is a length DWORD equal to key_len just before the key block
            marker = cleartext.rfind(struct.pack('<L', key_len))
            if marker != -1 and marker + 4 + key_len <= len(cleartext):
                cand = cleartext[marker + 4:marker + 4 + key_len]
                if len(cand) == key_len:
                    return cand
    return None


class VaultPolicy:
    """A Vault ``Policy.vpol`` file: the AES keys that protect the matching ``*.vcrd``."""

    def __init__(self, data):
        self.data = data
        self.blobs = [DpapiBlob(data[o:]) for o in _blob_offsets(data)]
        self.cleartexts = []
        self.aes_keys = []

    def decrypt(self, master_key, entropy=None):
        """Decrypt every wrapped blob with one master key (each blob names its GUID)."""
        return self._decrypt(lambda _blob: master_key, entropy)

    def decrypt_with_pool(self, pool, entropy=None):
        """Decrypt every wrapped blob, resolving each blob's master key from ``pool``."""
        return self._decrypt(lambda blob: pool.get_key(blob.mk_guid), entropy)

    def _decrypt(self, key_for, entropy):
        self.cleartexts = []
        self.aes_keys = []
        for blob in self.blobs:
            key = key_for(blob)
            if key is None:
                continue
            clear = blob.decrypt(key, entropy=entropy)
            if clear is None:
                continue
            self.cleartexts.append(clear)
            aes_key = _bcrypt_key_bytes(clear)
            if aes_key:
                self.aes_keys.append(aes_key)
        return self.cleartexts

    def key_material(self):
        """The concatenated decrypted key cleartexts (a stable fingerprint target)."""
        return b''.join(self.cleartexts)

    def aes_key_candidates(self, length):
        """Every ``length``-byte key found in the decrypted vpol cleartexts.

        The cleartext holds the vault's AES-128 and AES-256 keys, each preceded by its
        length. Several candidates may be returned; the right one is the one that
        decrypts a credential record to a well-formed structure.
        """
        keys = []
        marker = struct.pack('<L', length)
        for clear in self.cleartexts:
            start = 0
            while True:
                pos = clear.find(marker, start)
                if pos == -1:
                    break
                if pos + 4 + length <= len(clear):
                    keys.append(clear[pos + 4:pos + 4 + length])
                start = pos + 1
        return keys


class VaultCredential:
    """A Vault credential record (``*.vcrd``): outer structure, attribute map, and the
    AES decryption of its attributes under the keys from the matching ``Policy.vpol``.

    The record names a schema GUID (for example the Web Credentials / "Internet Explorer"
    schema); :func:`parse_web_credential` turns a decrypted attribute of that schema into
    the saved user name, resource and password.
    """

    def __init__(self, data):
        self.data = data
        self.schema_guid = DpapiBlob._guid(data[0:16])
        self.last_written_filetime = struct.unpack('<Q', data[20:28])[0]
        name_len = _u32(data, 36)
        self.friendly_name = data[40:40 + name_len].decode('utf-16-le', 'replace').rstrip('\x00')
        o = 40 + name_len
        maps_len = _u32(data, o)
        o += 4
        entries = []
        for _ in range(maps_len // 12):
            attr_id, offset, _unk = struct.unpack('<LLL', data[o:o + 12])
            entries.append((attr_id, offset))
            o += 12
        self.attributes = []
        for idx, (attr_id, offset) in enumerate(entries):
            end = entries[idx + 1][1] if idx + 1 < len(entries) else len(data)
            self.attributes.append({'id': attr_id, 'offset': offset,
                                    'raw': data[offset:end]})

    @staticmethod
    def _attribute_data(raw):
        """(IV, ciphertext) of one attribute, honouring the conditional VAULT_ATTRIBUTE layout.

        The attribute's Size field bounds the ciphertext exactly (Size counts the
        IVPresent byte, the IV length and IV, and the data), so trailing bytes between
        attributes are not read as ciphertext.
        """
        attr_id = _u32(raw, 0)
        o = 16                                   # id + three unknown dwords
        if len(raw) < o + 5:
            return b'', b''
        if raw[16:22] == b'\x00' * 6:            # optional 6-byte pad
            o += 6
        if attr_id >= 100:                       # extra dword for high ids
            o += 4
        if len(raw) < o + 5:
            return b'', b''
        size = _u32(raw, o)
        o += 4
        has_iv = raw[o]
        o += 1
        data_len = size - 1                      # Size includes the IVPresent byte
        iv = b''
        if has_iv and len(raw) >= o + 4:
            iv_len = _u32(raw, o)
            o += 4
            iv = raw[o:o + iv_len]
            o += iv_len
            data_len -= 4 + iv_len
        return iv, raw[o:o + max(0, data_len)]

    def decrypt(self, aes_keys):
        """``({attr_id: cleartext}, key)`` for the first key that decrypts the attributes.

        ``aes_keys`` are candidate AES keys from the matching vpol
        (:meth:`VaultPolicy.aes_key_candidates`). An attribute with a 16-byte IV is
        decrypted in CBC with it, otherwise with a zero IV; PKCS#7 padding is stripped.
        Returns ``({}, None)`` if no key yields any attribute cleartext.
        """
        keys = aes_keys if isinstance(aes_keys, (list, tuple)) else [aes_keys]

        def pkcs7(clear):
            pad = clear[-1] if clear else 0
            return clear[:-pad] if 1 <= pad <= 16 and clear[-pad:] == bytes([pad]) * pad else None

        for key in keys:
            decrypted = {}
            anchored = False
            good = True
            for attr in self.attributes:
                iv, data = self._attribute_data(attr['raw'])
                data = data[:len(data) // 16 * 16]   # trim inter-attribute padding to a CBC block
                if len(data) < 16:
                    continue
                clear = AES.new(key, AES.MODE_CBC, iv if len(iv) == 16 else b'\x00' * 16).decrypt(data)
                stripped = pkcs7(clear)
                if len(iv) == 16:
                    # The IV-bearing attributes are CBC with PKCS#7; a correct key leaves
                    # valid padding, so they anchor the key choice. The wider attributes
                    # (no IV) are not padded this way and are kept as decrypted.
                    if stripped is None:
                        good = False
                        break
                    anchored = True
                    decrypted[attr['id']] = stripped
                else:
                    decrypted[attr['id']] = stripped if stripped is not None else clear
            if good and anchored:
                return decrypted, key
        return {}, None


def parse_web_credential(cleartext):
    """``{user, resource, password}`` from a decrypted Web Credentials attribute, or None.

    Layout (VAULT schema "Internet Explorer"): Version, Count, Unknown, then three
    length-prefixed UTF-16LE fields each preceded by an id dword: user name, resource
    (the URL), and password.
    """
    if len(cleartext) < 24 or _u32(cleartext, 0) != 1:
        return None

    def read_string(offset):
        length = _u32(cleartext, offset)
        start = offset + 4
        text = cleartext[start:start + length].decode('utf-16-le', 'replace').rstrip('\x00')
        return text, start + length

    try:
        user, off = read_string(16)              # after version, count, unknown, Id1
        resource, off = read_string(off + 4)     # skip Id2
        password, _ = read_string(off + 4)        # skip Id3
    except (struct.error, IndexError):
        return None
    return {'user': user, 'resource': resource, 'password': password}
